{
  "title": "A Day of Wild Surprises",
  "summary": "Monkeys, markets, and a midnight-style beach finale the crew never saw coming.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": "m3",
      "note": "The sacred forest stays, because even a surprise day needs its cheeky locals. Rise and shine, the monkeys are already up.",
      "must_do_id": "m3"
    },
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": null,
      "note": "A market stop for local life and last-minute treasures. Terima kasih (thank you) to the bargaining gods."
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "A temple dip nobody expected, tucked just far enough to feel like a secret. The sun won’t wait, so we won’t either."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "Beach club after dark, because the night owls deserve a surprise too. I know a guy who says the lights hit different here."
    }
  ]
}
